/** 按决策卡 id 精确查找 */
export function getXiaoshiCase(id: string): DecisionCase | undefined {
  return XIAOSHI_CASES.find(c => c.id === id)
}

/** 按主题筛选决策卡 */
export function getXiaoshiCasesByTheme(theme: DecisionCase['theme']): readonly DecisionCase[] {
  return XIAOSHI_CASES.filter(c => c.theme === theme)
}
